package com.nexodb.ui;

import com.nexodb.db.*;import javax.swing.*;import javax.swing.border.EmptyBorder;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.nio.file.Path;import java.net.URLEncoder;import java.nio.charset.StandardCharsets;import java.util.*;import static com.nexodb.util.I18n.tr;

/** Dedicated native Redis and MongoDB browser; credentials live only in this panel. */
final class NativeDataExplorerPanel extends JPanel {
 private final JTextField redisHost=new JTextField("localhost",18),redisUser=new JTextField(12);private final JSpinner redisPort=new JSpinner(new SpinnerNumberModel(6379,1,65535,1)),redisLimit=new JSpinner(new SpinnerNumberModel(200,1,5000,50));private final JPasswordField redisPassword=new JPasswordField(14);private final JCheckBox redisTls=new JCheckBox("TLS");private final DefaultTableModel redisModel=model(new Object[]{tr("Clave"),tr("Tipo"),"TTL",tr("Vista previa")});
 private final JTextField mongoHost=new JTextField("localhost",18),mongoUser=new JTextField(12),mongoAuth=new JTextField("admin",9),mongoDatabase=new JTextField(12),mongoCollection=new JTextField(12),mongoDrivers=new JTextField(28);private final JSpinner mongoPort=new JSpinner(new SpinnerNumberModel(27017,1,65535,1)),mongoLimit=new JSpinner(new SpinnerNumberModel(100,1,1000,25));private final JPasswordField mongoPassword=new JPasswordField(14);private final JCheckBox mongoTls=new JCheckBox("TLS");private final JTextArea mongoOutput=new JTextArea();private SwingWorker<?,Void> worker;
 NativeDataExplorerPanel(){super(new BorderLayout());setBorder(new EmptyBorder(8,8,8,8));JTabbedPane tabs=new JTabbedPane();tabs.addTab("Redis",redis());tabs.addTab("MongoDB",mongo());add(tabs);}
 private JPanel redis(){JPanel panel=new JPanel(new BorderLayout(5,5));JToolBar bar=new JToolBar();bar.setFloatable(false);bar.add(new JLabel("Host: "));bar.add(redisHost);bar.add(new JLabel(" Puerto: "));bar.add(redisPort);bar.add(new JLabel(" Usuario: "));bar.add(redisUser);bar.add(new JLabel(" Clave: "));bar.add(redisPassword);bar.add(redisTls);bar.add(new JLabel(" Máx.: "));bar.add(redisLimit);JButton load=new JButton(tr("Conectar y explorar"));bar.add(load);JTable table=new JTable(redisModel);table.setAutoCreateRowSorter(true);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);table.getColumnModel().getColumn(0).setPreferredWidth(300);table.getColumnModel().getColumn(3).setPreferredWidth(500);load.addActionListener(e->run(load,()->{try(RedisNativeClient client=new RedisNativeClient(redisHost.getText().trim(),(Integer)redisPort.getValue(),redisTls.isSelected(),redisUser.getText().trim(),redisPassword.getPassword())){if(!"PONG".equalsIgnoreCase(client.ping()))throw new IllegalStateException("Redis no respondió PONG.");return client.scan((Integer)redisLimit.getValue());}},value->{redisModel.setRowCount(0);for(var key:(java.util.List<RedisNativeClient.Key>)value)redisModel.addRow(new Object[]{key.name(),key.type(),key.ttl(),key.preview()});}));panel.add(bar,BorderLayout.NORTH);panel.add(new JScrollPane(table));return panel;}
 private JPanel mongo(){JPanel panel=new JPanel(new BorderLayout(5,5));JPanel form=new JPanel(new GridLayout(3,1,3,3));JToolBar first=new JToolBar();first.setFloatable(false);first.add(new JLabel("Host: "));first.add(mongoHost);first.add(new JLabel(" Puerto: "));first.add(mongoPort);first.add(new JLabel(" Usuario: "));first.add(mongoUser);first.add(new JLabel(" Clave: "));first.add(mongoPassword);first.add(mongoTls);JToolBar second=new JToolBar();second.setFloatable(false);second.add(new JLabel("Auth DB: "));second.add(mongoAuth);second.add(new JLabel(" Base: "));second.add(mongoDatabase);second.add(new JLabel(" Colección: "));second.add(mongoCollection);second.add(new JLabel(" Máx.: "));second.add(mongoLimit);JToolBar third=new JToolBar();third.setFloatable(false);third.add(new JLabel(tr("Carpeta del controlador oficial: ")));third.add(mongoDrivers);JButton browse=new JButton("…"),listDb=new JButton(tr("Bases")),listCollections=new JButton(tr("Colecciones")),find=new JButton(tr("Documentos"));third.add(browse);third.add(listDb);third.add(listCollections);third.add(find);form.add(first);form.add(second);form.add(third);browse.addActionListener(e->{JFileChooser chooser=new JFileChooser();chooser.setFileSelectionMode(JFileChooser.DIRECTORIES_ONLY);if(chooser.showOpenDialog(DialogPosition.owner(this))==JFileChooser.APPROVE_OPTION)mongoDrivers.setText(chooser.getSelectedFile().getAbsolutePath());});listDb.addActionListener(e->mongo(listDb,"databases"));listCollections.addActionListener(e->mongo(listCollections,"collections"));find.addActionListener(e->mongo(find,"find"));mongoOutput.setEditable(false);mongoOutput.setFont(new Font(Font.MONOSPACED,Font.PLAIN,13));panel.add(form,BorderLayout.NORTH);panel.add(new JScrollPane(mongoOutput));return panel;}
 private void mongo(JButton source,String action){run(source,()->{char[] pass=mongoPassword.getPassword();String credentials=mongoUser.getText().isBlank()?"":encode(mongoUser.getText())+":"+encode(new String(pass))+"@";String options="?authSource="+encode(mongoAuth.getText())+(mongoTls.isSelected()?"&tls=true":"");String uri="mongodb://"+credentials+mongoHost.getText().trim()+":"+mongoPort.getValue()+"/"+options;try(MongoNativeClient client=new MongoNativeClient(Path.of(mongoDrivers.getText()),uri)){return switch(action){case "databases"->client.databases();case "collections"->client.collections(required(mongoDatabase,"base"));default->client.find(required(mongoDatabase,"base"),required(mongoCollection,"colección"),(Integer)mongoLimit.getValue());};}finally{Arrays.fill(pass,'\0');}},value->mongoOutput.setText(String.join("\n",(java.util.List<String>)value)));}
 private <T> void run(JButton button,java.util.concurrent.Callable<T> task,java.util.function.Consumer<T> done){if(worker!=null&&!worker.isDone())return;button.setEnabled(false);worker=new SwingWorker<T,Void>(){protected T doInBackground()throws Exception{return task.call();}protected void done(){try{done.accept(get());}catch(Exception error){JOptionPane.showMessageDialog(DialogPosition.owner(NativeDataExplorerPanel.this),message(error),tr("Explorador NoSQL"),JOptionPane.ERROR_MESSAGE);}finally{button.setEnabled(true);worker=null;}}};worker.execute();}
 private static DefaultTableModel model(Object[] columns){return new DefaultTableModel(columns,0){public boolean isCellEditable(int r,int c){return false;}};}private static String required(JTextField field,String label){String value=field.getText().trim();if(value.isBlank())throw new IllegalArgumentException("Indica "+label+".");return value;}private static String encode(String value){return URLEncoder.encode(value,StandardCharsets.UTF_8).replace("+","%20");}private static String message(Throwable error){while(error.getCause()!=null)error=error.getCause();return Objects.toString(error.getMessage(),error.getClass().getSimpleName());}
}
